import{At as e,Q as t,St as n,at as r,it as i,nt as a,ot as o,st as s,t as c,vt as l}from"./chunks/framework.B8IeflXD.js";var u=JSON.parse(`{"title":"Receipts: the machinery that keeps these documents true","description":"","frontmatter":{},"headers":[],"relativePath":"receipts-method.md","filePath":"pages/8_receipts.md"}`),d={name:`receipts-method.md`};function f(c,u,d,f,p,m){let h=n(`Mermaid`);return l(),i(`div`,null,[u[1]||=r(`<h1 id="receipts-the-machinery-that-keeps-these-documents-true" tabindex="-1">Receipts: the machinery that keeps these documents true <a class="header-anchor" href="#receipts-the-machinery-that-keeps-these-documents-true" aria-label="Permalink to “Receipts: the machinery that keeps these documents true”">​</a></h1><p>Four documents once gave four different unit-test counts. Two scripts now answer every countable claim from a machine source, and a third gate refuses the tree when a document and the repository disagree.</p><h2 id="contents" tabindex="-1">Contents <a class="header-anchor" href="#contents" aria-label="Permalink to “Contents”">​</a></h2><ol><li><a href="#the-three-programs">The three programs</a></li><li><a href="#what-the-lint-checks">What the lint checks</a></li><li><a href="#repointing-a-stale-citation">Repointing a stale citation</a></li><li><a href="#the-ledger-walks-the-program">The ledger walks the program</a></li><li><a href="#transclusion">Transclusion</a></li><li><a href="#commands">Commands</a></li><li><a href="#what-is-still-hand-written">What is still hand-written</a></li></ol><h2 id="the-three-programs" tabindex="-1">The three programs <a class="header-anchor" href="#the-three-programs" aria-label="Permalink to “The three programs”">​</a></h2>`,5),(l(),a(t,null,{default:e(()=>[s(h,{id:`mermaid-49`,class:`mermaid`,graph:`flowchart%20LR%0A%20%20subgraph%20sources%5BMachine%20sources%5D%0A%20%20%20%20TS%5BTypeScript%20program%5D%0A%20%20%20%20FS%5BFile%20system%5D%0A%20%20%20%20TESTS%5Btest%20files%5D%0A%20%20end%0A%20%20subgraph%20scripts%5BScripts%5D%0A%20%20%20%20PARITY%5Bscripts%2Fparity.mjs%5D%0A%20%20%20%20STATS%5Bscripts%2Fstats.mjs%5D%0A%20%20%20%20DOCS%5Bscripts%2Fdocs.mjs%5D%0A%20%20end%0A%20%20subgraph%20outputs%5BOutputs%5D%0A%20%20%20%20MATRIX%5Bdocs%2F1_parity.md%5D%0A%20%20%20%20PDATA%5Bsite%2Fparity.json%5D%0A%20%20%20%20SDATA%5Bsite%2Fstats.json%5D%0A%20%20%20%20DIST%5Bdocs%2Fdist%5D%0A%20%20end%0A%20%20TS%20--%3E%20PARITY%0A%20%20TS%20--%3E%20DOCS%0A%20%20FS%20--%3E%20DOCS%0A%20%20TESTS%20--%3E%20DOCS%0A%20%20PARITY%20--%3E%20MATRIX%0A%20%20PARITY%20--%3E%20PDATA%0A%20%20PDATA%20--%3E%20STATS%0A%20%20STATS%20--%3E%20SDATA%0A%20%20SDATA%20--%3E%20DOCS%0A%20%20PDATA%20--%3E%20DOCS%0A%20%20DOCS%20--%3E%20DIST%0A`})]),fallback:e(()=>[...u[0]||=[o(` Loading... `,-1)]]),_:1})),u[2]||=r(`<table tabindex="0"><thead><tr><th>script</th><th>answers</th><th>gate</th></tr></thead><tbody><tr><td><code>scripts/parity.mjs</code></td><td>which features exist, and where each one is implemented</td><td>exits non-zero on an untagged module</td></tr><tr><td><code>scripts/stats.mjs</code></td><td>every number the package prints about itself</td><td>never gates, records a <code>reason</code> beside each null</td></tr><tr><td><code>scripts/docs.mjs</code></td><td>whether a document agrees with the repository</td><td>exits non-zero on any violation</td></tr></tbody></table><h2 id="what-the-lint-checks" tabindex="-1">What the lint checks <a class="header-anchor" href="#what-the-lint-checks" aria-label="Permalink to “What the lint checks”">​</a></h2><p>Six checks, one line of output each, naming the file, the line, and the fix.</p><table tabindex="0"><thead><tr><th>check</th><th>fires when</th></tr></thead><tbody><tr><td>stale citation</td><td>the cited line does not hold the symbol named beside it</td></tr><tr><td>missing file</td><td>a backticked path resolves nowhere</td></tr><tr><td>unknown symbol</td><td>a name sits beside a source path that neither exports nor mentions it</td></tr><tr><td>hard-coded number</td><td>a bare digit sits within three tokens of a countable noun</td></tr><tr><td>unknown key</td><td>a placeholder resolves in no data source</td></tr><tr><td>unknown test</td><td>a quoted sentence matches no declared test name</td></tr></tbody></table><p>One line per violation, in that order:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>docs/0_api.md:113 cites src/10_render.ts:348 but &quot;bind&quot; is at :580</span></span>
<span class="line"><span>README.md:44 names src/fromTree.ts which does not exist</span></span>
<span class="line"><span>README.md:48 names axisOf, not exported from src/1_axis.ts (exports: axisOfEntries, axisOfTree)</span></span>
<span class="line"><span>PITCH.md:22 hard-codes &quot;418 unit tests&quot;; use {{stats.tests.unit}}</span></span>
<span class="line"><span>docs/6_why.md:41 references {{bench.expand.median}}, no such key</span></span>
<span class="line"><span>docs/2_guide.md:59 quotes &quot;clamps to the column minimum width&quot;; no test has that name</span></span></code></pre></div><p>Exported names come from the TypeScript compiler API, through the same <code>typescript/unstable/sync</code> loader the parity script drives. A citation and a name are paired only inside one clause, so a competitor table naming another library&#39;s API in one cell and a source path in the next stays quiet.</p><h3 id="deliberate-silences" tabindex="-1">Deliberate silences <a class="header-anchor" href="#deliberate-silences" aria-label="Permalink to “Deliberate silences”">​</a></h3><table tabindex="0"><thead><tr><th>situation</th><th>why the lint says nothing</th></tr></thead><tbody><tr><td>the name beside a citation is absent from the cited file</td><td>the pairing was prose, not a claim about that file</td></tr><tr><td>the name occurs on more than six lines of the cited file</td><td>no single line can be the one meant</td></tr><tr><td>a bare digit inside a fenced code block</td><td>a code sample counts what it likes</td></tr><tr><td>a digit and a noun separated by a table cell wall</td><td>one column never counts the noun in the next</td></tr><tr><td>a quoted fragment shorter than three words</td><td>a test name is a sentence a person wrote</td></tr></tbody></table><h2 id="repointing-a-stale-citation" tabindex="-1">Repointing a stale citation <a class="header-anchor" href="#repointing-a-stale-citation" aria-label="Permalink to “Repointing a stale citation”">​</a></h2><p><code>--fix</code> rewrites the line number of a citation whose symbol it can locate elsewhere in the same file. A citation with no name beside it is left alone and printed instead, because the script has nothing to search for and a guess would be worse than the drift.</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/docs.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fix</span></span></code></pre></div><h2 id="the-ledger-walks-the-program" tabindex="-1">The ledger walks the program <a class="header-anchor" href="#the-ledger-walks-the-program" aria-label="Permalink to “The ledger walks the program”">​</a></h2><p>Every module the TypeScript program compiles under <code>src/</code> is a tagging surface. A module either carries at least one <code>@feature</code> or <code>@feature-declared</code> tag, or it opts out in its own first line.</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// @no-features: pure layout arithmetic, every caller is already tagged</span></span></code></pre></div><p><code>index.ts</code> and <code>features.ts</code> never carry a claim, and <code>src/test/</code> is a fixture kit. Everything else is checked, so adding a module is what reminds the author to place its tag.</p><h3 id="the-last-caller-warning" tabindex="-1">The last-caller warning <a class="header-anchor" href="#the-last-caller-warning" aria-label="Permalink to “The last-caller warning”">​</a></h3><p>For every tagged declaration the checker is asked who references it. A declaration with exactly one reference is its own only mention, and the matrix is promising behaviour that no library code reaches. It prints as a warning rather than a failure: <code>tsconfig.json</code> excludes the test files, and <code>demo/</code>, <code>site/</code>, <code>bench/</code>, and <code>tests/</code> are separate projects, so an export whose only callers live in a test or the demo is correct code that this program cannot see.</p><h2 id="transclusion" tabindex="-1">Transclusion <a class="header-anchor" href="#transclusion" aria-label="Permalink to “Transclusion”">​</a></h2><p><code>--render</code> expands placeholders into <code>docs/dist/</code>, one file per document, leaving the sources readable on their own.</p><table tabindex="0"><thead><tr><th>prefix</th><th>source</th><th>a key under it</th></tr></thead><tbody><tr><td><code>stats</code></td><td><code>site/stats.json</code></td><td><code>stats.tests.unit</code></td></tr><tr><td><code>bench</code></td><td><code>bench/results.json</code>, keyed by a slug of each benchmark name</td><td><code>bench.read_view_flat_no_write_1k_rows.median</code></td></tr><tr><td><code>parity</code></td><td><code>site/parity.json</code></td><td><code>parity.implemented</code></td></tr></tbody></table><p>A key is written in double braces and walks the JSON by its dots:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{{stats.tests.unit}}</span></span></code></pre></div><p>A key landing on an array yields its length. A key landing on a group carrying a headline number under <code>tests</code>, <code>count</code>, <code>total</code>, or <code>value</code> collapses to that number, which is why the key above prints a count rather than an object.</p><p>Values as this file was last rendered:</p><table tabindex="0"><thead><tr><th>key</th><th>value</th></tr></thead><tbody><tr><td><code>stats.tests.unit</code></td><td>415</td></tr><tr><td><code>stats.source.testFiles</code></td><td>25</td></tr><tr><td><code>stats.epics.count</code></td><td>12</td></tr><tr><td><code>stats.source.sourceLines</code></td><td>7,758</td></tr><tr><td><code>stats.bundle.library.totalGzipBytes</code></td><td>34,060</td></tr><tr><td><code>parity.features</code></td><td>47</td></tr><tr><td><code>parity.implemented</code></td><td>24</td></tr><tr><td><code>parity.declaredOnly</code></td><td>9</td></tr><tr><td><code>parity.untagged</code></td><td>0</td></tr><tr><td><code>parity.unread</code></td><td>10</td></tr></tbody></table><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to “Commands”">​</a></h2><table tabindex="0"><thead><tr><th>command</th><th>effect</th></tr></thead><tbody><tr><td><code>pnpm parity</code></td><td>rewrites <code>docs/1_parity.md</code> and <code>site/parity.json</code>, gates on untagged modules</td></tr><tr><td><code>pnpm docs</code></td><td>lints, prints one line per violation, exits non-zero</td></tr><tr><td><code>pnpm docs:fix</code></td><td>repoints the citations it can, reports the ones it refuses</td></tr><tr><td><code>pnpm docs:render</code></td><td>writes <code>docs/dist/</code>, never gates</td></tr><tr><td><code>pnpm receipts</code></td><td>typecheck, tests, build, then the lint</td></tr></tbody></table><h2 id="what-is-still-hand-written" tabindex="-1">What is still hand-written <a class="header-anchor" href="#what-is-still-hand-written" aria-label="Permalink to “What is still hand-written”">​</a></h2><table tabindex="0"><thead><tr><th>claim</th><th>who checks it</th></tr></thead><tbody><tr><td>prose describing behaviour</td><td>nobody, read it</td></tr><tr><td>a competitor&#39;s API name or bundle size</td><td>nobody, <code>docs/parity.mui.json</code> carries a citation URL per row</td></tr><tr><td>a benchmark narrative</td><td>the numbers come from <code>bench/README.md</code>, the reading of them does not</td></tr></tbody></table>`,30)])}var p=c(d,[[`render`,f]]);export{u as __pageData,p as default};